-- #987 wave 1 (pure additions): Borean Tundra creature abilities, imported from DeltaTho PR 15 file 2026_10_24_95_world.sql.
-- 74 creatures, 120 smart_scripts rows. Only creatures that have NO source_type 0 rows today are written here;
-- scripts that would replace existing rows are wave 2. Filters/fixes: see (not shipped)
-- Idempotent: DELETE of the listed entries then INSERT. AIName is set to SmartAI only where AIName and ScriptName are empty.
-- Undo: DELETE FROM smart_scripts WHERE source_type=0 AND FIND_IN_SET(entryorguid, <entries below>); and
--   UPDATE creature_template SET AIName='' WHERE FIND_IN_SET(entry, <entries below>); (entries that already had AIName SmartAI: see backup in (not shipped).

SET @ENTRIES := '24765,25209,25211,25226,25227,25242,25243,25244,25294,25311,25338,25351,25383,25386,25387,25393,25415,25417,25419,25427,25445,25446,25451,25453,25454,25464,25467,25468,25481,25496,25498,25514,25520,25521,25522,25523,25600,25609,25615,25619,25622,25623,25660,25684,25685,25686,25687,25699,25701,25709,25717,25725,25764,25774,25800,25801,25803,25844,25981,26094,26103,26115,26202,26266,26449,26451,27106,27107,27108,27110,27189,32534,51877,51889';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE `AIName` = '' AND `ScriptName` = '' AND FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
